static unsigned gate_schedules,gate_caches;
static int gate_override;
static cr_flow gate_provider(void*p,cr_model*c,const cr_request*q,cr_result*out){(void)p;CHECK(c==&m.receive&&c->memory==&m.memory);memset(out,0,sizeof(*out));
 if(q->operation==CR_CSR_CLEAR||q->operation==CR_CSR_SET){CHECK(q->target==0x800&&q->value==136);return CR_RETURNED;}
 if(q->operation==CR_COPY&&q->va==0x82c0)gate_caches++;
 if(q->target==0x9102){unsigned i;gate_schedules++;CHECK(q->va==0x106de&&q->count==4);CHECK(q->arguments[0]==0x1063c&&q->arguments[1]==0&&q->arguments[2]==2000&&q->arguments[3]==0);for(i=0;i<4;i++)CHECK(q->argument_known[i]==UINT32_MAX);if(gate_override)return gate_override==1?CR_HALT:CR_TRANSFER;}
 return ta_receive_primitive(&m,q,out);
}
static void gate_fresh(void){unsigned i;cr_backend b;fresh(TC_RUNTIME);put(A(0xc790),0,1);put(A(0xc792),7,2);put(A(0xc794),1,1);put(A(0xc795),0,1);put(A(0xc796),65534,2);put(A(0x4054),A(0xc298),4);put(A(0xc29c),0,1);put(A(0x40c1),7,1);put(A(0xbfb1),1,1);for(i=0;i<32*12;i++)put(A(0xc034)+i,0,1);for(i=0;i<19*12;i++)put(A(0xc1b4)+i,0,1);memset(&b,0,sizeof(b));b.invoke=gate_provider;ta_set_receive_backend(&m,&b);gate_schedules=gate_caches=0;gate_override=0;}
static void gate_record(int valid){put(A(0xc034),0x3e9,2);put(A(0xc036),8,1);put(A(0xc03e),valid?0xec:0,1);}
static cr_flow direct_gate(void){cr_arguments a;memset(&a,0,sizeof(a));a.record.kind=CR_RAM;a.record.address=A(0xc034);a.argument.value=0x1051c;a.argument.known=UINT32_MAX;return ta_dispatch_receive(&m,0x106b8,&a);}
static void rejected(void){group("invalid checksum3E9 copies cache13 and returns without clearing counter or scheduling");gate_fresh();gate_record(0);CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_RETURNED);CHECK(gate_caches==1&&gate_schedules==0&&get(A(0x40c1),1)==7);CHECK(get(A(0xc1b4)+13*12,2)==0x3e9&&get(A(0xc1b4)+13*12+10,1)==0);CHECK(m.receive.consumed==1&&!m.halted&&get(TF_REGISTRY+4,4)==0);}
static void accepted(void){uint32_t node=0;group("valid checksum3E9 clears counter schedules actualcandidate timer and stops at actualAD16 suffix");gate_fresh();gate_record(1);put(A(0xc040),0x2b4,2);CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_HALT);CHECK(gate_caches==1&&gate_schedules==1&&get(A(0x40c1),1)==0);CHECK(m.receive.boundary_va==0x1500e&&m.receive.boundary_address==0xad16);CHECK(get(TF_REGISTRY+4,4)==0x1063c&&get(TF_REGISTRY+8,4)==0);CHECK(m.memory.last_ticks==3200&&m.last_schedule_result==0);CHECK(rc_timer_find(&adapter,3,1,&node)==1&&node!=0);if(node)CHECK(get(node+8,4)==32000);CHECK(get(A(0xc040),2)==0x2b4&&m.receive.consumed==1);CHECK(get(A(0xc1b4)+13*12+10,1)==0xec);}
static void full_registry(void){unsigned i;uint32_t node=0;group("full registry returns scheduler failure scalar but106B8 still returns originalpredicate true");gate_fresh();gate_record(1);for(i=0;i<15;i++)put(TF_REGISTRY+12*i+4,0x18000+4*i,4);CHECK(direct_gate()==CR_RETURNED);CHECK(gate_schedules==1&&get(A(0x40c1),1)==0&&m.last_schedule_result==1);CHECK(m.receive.result_defined&&m.receive.result==1&&m.receive.result_known==UINT32_MAX);CHECK(rc_timer_find(&adapter,3,1,&node)==1&&node==0);CHECK(!m.halted);}
static void missing_clock(void){uint32_t node=0;group("missing actual clock retains clear and registry prefix but stops scheduler before nextqueue");gate_fresh();gate_record(1);put(A(0xc040),0x2b4,2);adapter.hooks.clock=NULL;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_HALT);CHECK(gate_schedules==1&&get(A(0x40c1),1)==0);CHECK(m.receive.boundary_va==0x106de&&m.receive.boundary_address==0x9102);CHECK(get(TF_REGISTRY+4,4)==0x1063c&&get(A(0xc040),2)==0x2b4);CHECK(rc_timer_find(&adapter,3,1,&node)==0&&adapter.fault&&node==0);CHECK(get(A(0x3098),4)==0);}
static void halted(void){group("schedule externalHALT preserves counter/cache prefix without default fallback");gate_fresh();gate_record(1);gate_override=1;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_HALT);CHECK(gate_caches==1&&gate_schedules==1&&get(A(0x40c1),1)==0);CHECK(get(TF_REGISTRY+4,4)==0&&m.memory.schedule_requests==0);CHECK(m.receive.boundary_va==0x106de&&m.receive.boundary_address==0x9102);}
static void transferred(void){uint32_t effects;group("schedule externalTRANSFER preserves prefix and withholds repeated activation");gate_fresh();gate_record(1);put(A(0xc040),0x2b4,2);gate_override=2;effects=m.memory.unknown_effects;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_TRANSFER);CHECK(gate_schedules==1&&m.transferred&&get(A(0x40c1),1)==0);CHECK(m.memory.unknown_effects==effects&&get(TF_REGISTRY+4,4)==0);CHECK(get(A(0xc040),2)==0x2b4&&m.receive.consumed==1);CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_TRANSFER&&gate_schedules==1);}
static void unknown_checksum(void){group("ambiguous fixed checksumbyte preserves cache masks and stops106C6 before sideeffects");gate_fresh();gate_record(1);m.memory.known[0xc03e]=0;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_HALT);CHECK(gate_caches==1&&gate_schedules==0&&get(A(0x40c1),1)==7);CHECK(m.receive.boundary_va==0x106c6&&get(TF_REGISTRY+4,4)==0);CHECK(m.memory.known[0xc1b4+13*12+10]==0);}
static void callback_boundary(void){uint32_t node=0;uint16_t events=0;group("actual timer event isdelivered but unported1063C callback stays unknown");gate_fresh();gate_record(1);CHECK(direct_gate()==CR_RETURNED);CHECK(rc_timer_find(&adapter,3,1,&node)==1&&node!=0);raw_clock=32000;CHECK(rc_timer_pump(&adapter)==1);CHECK(rc_take_event(&adapter,3,&events)==1&&events==1);CHECK(ta_dispatch_runtime(&m,events)==events);CHECK(m.halted&&m.memory.last_callback==0x1063c);CHECK(get(TF_REGISTRY+4,4)==0&&get(TF_REGISTRY+8,4)==0);}
int main(int argc,char**argv){FILE*f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];rejected();accepted();full_registry();missing_clock();halted();transferred();unknown_checksum();callback_boundary();printf("GATE_INTEGRATION_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no network=no\n",groups,checks,failures);return failures?1:0;}
